select case when id = 1 then json_object('n', ifnull(n, 0)) else json_object('n', id) end as j, case when id = 1 then json_array(ifnull(n, 0)) else json_array(id) end as a, case when id = 1 then json_array(ifnull(big, 0)) else json_array(id) end as b, case when id = 1 then json_object(cast(id as text), ifnull(n, 0)) else json_object(cast(id as text), id) end as m from loose
